from datetime import datetime,timezone
from .schemas import Strategy
def g(o,k,d=None): return o.get(k,d) if isinstance(o,dict) else getattr(o,k,d)
def generate_strategies(incident):
    assets=g(incident,'affectedAssets',[]) or []; risk=int(g(incident,'riskScore',70) or 70); n=max(1,len(assets)); critical=sum(str(g(a,'criticality','TIER 2')).upper()=='TIER 0' for a in assets)
    return [Strategy(id='STR-ISOLATE',name='Contain and Isolate',description='Isolate high-risk devices and disable compromised identities.',actions=['Isolate Device','Disable User'],risk_reduction=min(95,35+n*5+critical*15),downtime_hours=round(1.5+n*.75,2),recovery_time_hours=round(3+n*1.2,2),operational_cost=round(1800+n*650,2),confidence=round(min(.97,.70+critical*.05),3),rationale=['Fast containment limits propagation.']),Strategy(id='STR-BLOCK',name='Network Containment',description='Block malicious indicators while preserving availability.',actions=['Block IP','Create Ticket'],risk_reduction=min(82,25+n*7),downtime_hours=round(.5+n*.25,2),recovery_time_hours=round(2+n*.6,2),operational_cost=round(900+n*300,2),confidence=.86,rationale=['Lower operational disruption.']),Strategy(id='STR-FULL',name='Full Response',description='Broad containment with ticketing and reporting.',actions=['Block IP','Disable User','Isolate Device','Create Ticket','Generate Report'],risk_reduction=min(99,55+n*8+critical*8),downtime_hours=round(3+n*1.1,2),recovery_time_hours=round(6+n*1.8,2),operational_cost=round(4200+n*1200,2),confidence=round(min(.99,.80+critical*.04),3),rationale=['Maximizes risk reduction at higher cost and downtime.'])]
